def _spectral_peakiness(data, frequency_range=None):
    """Measure how concentrated the spectral energy of ``data`` is.

    A sharp, well-defined peak (a good registration reference) has a high
    peak-to-RMS ratio, whereas broadband noise or a badly corrupted transient
    has a low ratio.  The optional ``frequency_range`` restricts the
    measurement to the spectral window used for registration.
    """
    spectrum = numpy.abs(data.spectrum())
    weights = _frequency_weights(data, frequency_range)
    if weights is not None:
        spectrum = spectrum * numpy.asarray(weights)

    energy = numpy.sqrt(numpy.sum(spectrum * spectrum))
    if not numpy.isfinite(energy) or energy == 0:
        return -numpy.inf
    return float(numpy.max(spectrum) / energy)


def dynamic_reference(series):
    """Build a common reference for a dynamic series.

    A good reference transient has a sharp, concentrated spectral peak, so the
    most peak-like transient in the series is used as the initial reference.
    The caller can also supply an externally acquired reference (for example a
    separately averaged water signal) which will take precedence in
    :func:`register_dynamic_series`.
    """
    series = [item.squeeze() for item in series]
    if len(series) == 0:
        raise ValueError("series must contain at least one transient")
    if len(series) == 1:
        return series[0].copy()
    best_index = max(
